using ToneCustoms.ShellStudio.Core;using ToneCustoms.ShellStudio.Validation;
namespace ToneCustoms.ShellStudio.Export;
public sealed class ExportOrchestrator { public async Task<ExportReport> RunAsync(ShellProject project,string blenderExe,string bridgeScript,string output){var start=DateTime.UtcNow;var steps=new List<ExportStep>();var issues=new ProjectValidator().Validate(project);if(issues.Any(x=>x.Severity==ValidationSeverity.Error)){steps.Add(new("Project validation",false,"Project has blocking errors"));return new(start,DateTime.UtcNow,false,project.Name,null,steps,issues.Where(x=>x.Severity==ValidationSeverity.Error).Select(x=>x.Message).ToArray());}steps.Add(new("Project validation",true,"Project validation passed"));var gtaDir=Path.Combine(output,"gta-output");var diag=await new GtaExportCoordinator().RunAsync(project,blenderExe,bridgeScript,gtaDir);steps.AddRange(diag.Steps);if(!diag.Success)return new(start,DateTime.UtcNow,false,project.Name,null,steps,new[]{"Blender/Sollumz conversion did not complete successfully"});var errors=new GtaOutputVerifier().Verify(Path.Combine(gtaDir,"stream"));steps.Add(new("GTA output verification",errors.Count==0,errors.Count==0?"Verified GTA model and collision output":"GTA output incomplete"));if(errors.Count>0)return new(start,DateTime.UtcNow,false,project.Name,null,steps,errors);var resource=new FiveMResourceBuilder().Prepare(project,output);steps.Add(new("FiveM resource",true,"Resource built"));return new(start,DateTime.UtcNow,true,project.Name,resource,steps,Array.Empty<string>());} }
